CREATE FUNCTION public.lock_tenant_currency(_tenant_id uuid) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _tenant_id IS NULL THEN RAISE EXCEPTION 'Unknown organization'; END IF; IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'Currency-coordinated writes require READ COMMITTED isolation'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('creditvoice.currency:' || _tenant_id::text,0)); END $$;
REVOKE ALL ON FUNCTION public.lock_tenant_currency(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.lock_tenant_currency(uuid) TO service_role;
CREATE FUNCTION public.guard_currency_related_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE curr text; BEGIN PERFORM public.lock_tenant_currency(new.tenant_id); SELECT currency_code INTO curr FROM public.tenants WHERE id=new.tenant_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown organization'; END IF; IF to_jsonb(new) ? 'currency_code' AND (to_jsonb(new)->>'currency_code') IS DISTINCT FROM curr THEN RAISE EXCEPTION 'Financial records must use the organization currency'; END IF; RETURN new; END $$;
REVOKE ALL ON FUNCTION public.guard_currency_related_insert() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.customer_accounts FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.ledger_entries FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.ledger_accounts FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.transfers FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.financial_idempotency FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE TRIGGER a_currency_serialization BEFORE INSERT ON public.financial_failure_events FOR EACH ROW EXECUTE FUNCTION public.guard_currency_related_insert();
CREATE FUNCTION public.tenant_has_currency_history(_tenant_id uuid) RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.ledger_entries WHERE tenant_id=_tenant_id) OR EXISTS(SELECT 1 FROM public.ledger_accounts WHERE tenant_id=_tenant_id) OR EXISTS(SELECT 1 FROM public.transactions WHERE tenant_id=_tenant_id) OR EXISTS(SELECT 1 FROM public.transfers WHERE tenant_id=_tenant_id) OR EXISTS(SELECT 1 FROM public.financial_idempotency WHERE tenant_id=_tenant_id) OR EXISTS(SELECT 1 FROM public.financial_failure_events WHERE tenant_id=_tenant_id) $$;
REVOKE ALL ON FUNCTION public.tenant_has_currency_history(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tenant_has_currency_history(uuid) TO service_role;
CREATE FUNCTION public.enforce_currency_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE why text; n integer; stamp timestamptz; BEGIN IF new.currency_code IS NOT DISTINCT FROM old.currency_code THEN RETURN new; END IF; IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only Super Admins may change currency'; END IF; IF current_setting('app.currency_change_tenant',true) IS DISTINCT FROM old.id::text THEN RAISE EXCEPTION 'Use the approved currency change operation'; END IF; why:=nullif(trim(current_setting('app.currency_change_reason',true)),''); IF why IS NULL OR length(why)>1000 THEN RAISE EXCEPTION 'A currency change reason is required (1 to 1000 characters)'; END IF; PERFORM public.lock_tenant_currency(old.id); IF NOT EXISTS(SELECT 1 FROM public.currencies WHERE code=new.currency_code AND is_active) THEN RAISE EXCEPTION 'Target currency must be active'; END IF; IF public.tenant_has_currency_history(old.id) THEN RAISE EXCEPTION 'Currency change blocked: organization has financial history'; END IF; PERFORM 1 FROM public.customer_accounts WHERE tenant_id=old.id ORDER BY id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.customer_accounts WHERE tenant_id=old.id AND (currency_code IS DISTINCT FROM old.currency_code OR balance<>0 OR credit_limit<>0)) THEN RAISE EXCEPTION 'Currency change blocked: accounts must be consistent and have zero balances and credit limits'; END IF; PERFORM set_config('app.currency_change_target',new.currency_code,true); UPDATE public.customer_accounts SET currency_code=new.currency_code WHERE tenant_id=old.id; GET DIAGNOSTICS n=ROW_COUNT; PERFORM set_config('app.currency_change_target','',true); stamp:=clock_timestamp(); INSERT INTO public.audit_logs(tenant_id,actor_id,actor_role,event_type,entity_type,entity_id,metadata,created_at) VALUES(old.id,auth.uid(),'SUPER_ADMIN','CURRENCY_CHANGED','tenant',old.id,jsonb_build_object('old_currency',old.currency_code,'new_currency',new.currency_code,'reason',why,'changed_at',stamp,'accounts_updated',n),stamp); RETURN new; END $$;
REVOKE ALL ON FUNCTION public.enforce_currency_change() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER a_enforce_currency_change BEFORE UPDATE OF currency_code ON public.tenants FOR EACH ROW EXECUTE FUNCTION public.enforce_currency_change();
CREATE OR REPLACE FUNCTION public.guard_account_balance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_setting('app.ledger_posting',true) IS DISTINCT FROM 'on' THEN IF new.balance IS DISTINCT FROM old.balance THEN RAISE EXCEPTION 'Balances can only change through ledger postings'; END IF; IF new.tenant_id IS DISTINCT FROM old.tenant_id OR new.customer_id IS DISTINCT FROM old.customer_id OR new.account_number IS DISTINCT FROM old.account_number THEN RAISE EXCEPTION 'Account identity and currency are immutable'; END IF; IF new.currency_code IS DISTINCT FROM old.currency_code AND NOT (pg_trigger_depth()>1 AND public.is_super_admin() AND old.balance=0 AND old.credit_limit=0 AND new.currency_code=current_setting('app.currency_change_target',true) AND NOT public.tenant_has_currency_history(old.tenant_id)) THEN RAISE EXCEPTION 'Account identity and currency are immutable'; END IF; IF new.credit_limit<0 THEN RAISE EXCEPTION 'Credit limit cannot be negative'; END IF; END IF; RETURN new; END $$;
CREATE FUNCTION public.change_organization_currency(_tenant_id uuid,_currency text,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_currency text; BEGIN IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only Super Admins may change currency'; END IF; PERFORM public.lock_tenant_currency(_tenant_id); SELECT currency_code INTO before_currency FROM public.tenants WHERE id=_tenant_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown organization'; END IF; IF before_currency IS NOT DISTINCT FROM _currency THEN RAISE EXCEPTION 'Organization already uses this currency'; END IF; PERFORM set_config('app.currency_change_tenant',_tenant_id::text,true); PERFORM set_config('app.currency_change_reason',coalesce(_reason,''),true); UPDATE public.tenants SET currency_code=_currency WHERE id=_tenant_id; PERFORM set_config('app.currency_change_reason','',true); PERFORM set_config('app.currency_change_tenant','',true); RETURN jsonb_build_object('tenant_id',_tenant_id,'old_currency',before_currency,'new_currency',_currency); END $$;
REVOKE ALL ON FUNCTION public.change_organization_currency(uuid,text,text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.change_organization_currency(uuid,text,text) TO authenticated;
DO $patch$ DECLARE name text; signature text; lookup text; definition text; BEGIN FOR name,signature,lookup IN VALUES ('post_credit','public.post_credit(uuid,numeric,public.transaction_type,text,text)','SELECT tenant_id FROM public.customer_accounts WHERE id=_account_id'),('execute_transfer','public.execute_transfer(uuid,uuid,numeric,text,text)','SELECT tenant_id FROM public.customer_accounts WHERE id=_sender_account_id'),('reverse_transfer','public.reverse_transfer(uuid,text)','SELECT tenant_id FROM public.transfers WHERE id=_transfer_id') LOOP definition:=pg_get_functiondef(signature::regprocedure); IF position('perform public.lock_tenant_currency' in lower(definition))=0 THEN IF position(E'begin\n' in definition)=0 THEN RAISE EXCEPTION 'Unexpected financial function shape: %',name; END IF; definition:=replace(definition,E'begin\n',E'begin\n  perform public.lock_tenant_currency(('||lookup||E'));\n'); EXECUTE definition; END IF; END LOOP; END $patch$;